package docscheck_test

import (
	"fmt"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"testing"
)

// One source for cited figures (roadmap I3): docs/reference/bench.md is
// generated by `make bench`; every place that quotes its totals is checked
// against it here, so a refreshed bench.md without the citations fails.

// benchFigures are the totals of docs/reference/bench.md that other docs quote.
// Percentages keep bench.md's one-decimal text.
type benchFigures struct {
	Fixtures         int    // synthetic corpus TOTAL fixtures
	Raw              string // TOTAL saving % without CCR
	CCR              string // TOTAL saving % with CCR
	LosslessFixtures int    // lossless class fixtures
	Lossless         string // lossless class saving %
	BalancedOutputs  int    // rows of the Balanced table
	BalancedLossless string // Balanced TOTAL, compressor alone %
	Balanced         string // Balanced TOTAL saving %
}

// tableCells splits one Markdown table row into trimmed cells.
func tableCells(line string) []string {
	parts := strings.Split(strings.Trim(strings.TrimSpace(line), "|"), "|")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return parts
}

// parseBenchFigures reads the totals out of bench.md's three tables.
func parseBenchFigures(md string) (benchFigures, error) {
	var f benchFigures
	var err error
	inBalanced, found := false, 0
	for _, line := range strings.Split(md, "\n") {
		if strings.HasPrefix(line, "## ") {
			inBalanced = strings.HasPrefix(line, "## Balanced")
			continue
		}
		if !strings.HasPrefix(line, "|") || strings.HasPrefix(line, "|--") || strings.HasPrefix(line, "|---") {
			continue
		}
		c := tableCells(line)
		switch {
		case inBalanced && c[0] == "TOTAL" && len(c) == 6:
			f.BalancedLossless, f.Balanced = c[3], c[5]
			found++
		case inBalanced && c[0] != "Fixture" && len(c) == 6:
			f.BalancedOutputs++
		case !inBalanced && c[0] == "TOTAL" && len(c) == 10:
			if f.Fixtures, err = strconv.Atoi(c[2]); err != nil {
				return f, err
			}
			f.Raw, f.CCR = c[5], c[9]
			found++
		case !inBalanced && c[0] == "lossless" && len(c) == 5:
			if f.LosslessFixtures, err = strconv.Atoi(c[1]); err != nil {
				return f, err
			}
			f.Lossless = c[4]
			found++
		}
	}
	if found != 3 || f.BalancedOutputs == 0 {
		return f, fmt.Errorf("bench.md: found %d of 3 total rows and %d balanced outputs; did its table layout change?", found, f.BalancedOutputs)
	}
	return f, nil
}

// comma writes a bench percentage the Portuguese way (67.0 -> 67,0).
func comma(s string) string { return strings.ReplaceAll(s, ".", ",") }

// benchCitations are the phrases each doc must carry, built from f. Whitespace
// in the doc is collapsed before matching, so a phrase may wrap.
func benchCitations(f benchFigures) map[string][]string {
	n, ln, bn := strconv.Itoa(f.Fixtures), strconv.Itoa(f.LosslessFixtures), strconv.Itoa(f.BalancedOutputs)
	return map[string][]string{
		"README.md": {
			f.CCR + "% fewer bytes on a " + n + "-fixture benchmark",
			"**" + f.Lossless + "% fewer bytes** | " + ln + " lossless fixtures",
			"**" + f.CCR + "% fewer bytes** | " + n + "-fixture synthetic corpus (" + f.Raw + "% with CCR off)",
			"**" + f.Balanced + "% fewer bytes** | " + bn + " real outputs",
			f.BalancedLossless + "% with the lossless compressor alone",
		},
		"docs/pt-br/README.md": {
			comma(f.CCR) + "% menos bytes num benchmark de " + n + " fixtures",
			"**" + comma(f.Lossless) + "% menos bytes** | " + ln + " fixtures sem perda",
			"**" + comma(f.CCR) + "% menos bytes** | Corpus sintético de " + n + " fixtures (" + comma(f.Raw) + "% com CCR desligado)",
			"**" + comma(f.Balanced) + "% menos bytes** | " + bn + " saídas reais",
			comma(f.BalancedLossless) + "% só com o compressor sem perda",
		},
		// The Portuguese benchmark page writes decimals with a dot, as bench.md.
		"docs/pt-br/referencia/benchmarks.md": {
			"corpus sintético de " + n + " fixtures compactadas",
			"**Total do Corpus (" + n + " fixtures)**",
			"| **" + f.Raw + "%** |",
			"| **" + f.CCR + "%** |",
			"| **Lossless (Sem Perda)** | **" + ln + "** |",
			"**" + f.Lossless + "% de economia média de bytes**",
		},
		"llms.txt": {
			n + "-fixture synthetic corpus",
			f.CCR + "% fewer with CCR on, " + f.Raw + "% with it off, " + f.Lossless + "% on the " + ln + " lossless fixtures",
		},
		"docs/true-north.md": {
			n + "-fixture synthetic corpus (" + f.Raw + "% raw, " + f.CCR + "% with CCR; " + f.Lossless + "% on lossless families",
		},
		"docs/guides/ccr.md": {
			"total saving is " + f.Raw + "% with CCR off and " + f.CCR + "% with CCR on",
		},
		"docs/features/compaction.md": {
			"the total saving goes from " + f.Raw + "% to " + f.CCR + "%",
		},
		"docs/guides/evidence.md": {
			"On the " + n + "-fixture synthetic corpus",
			"**" + f.CCR + "% byte reduction with CCR** (" + f.Raw + "% raw without CCR), reaching " + f.Lossless + "% on lossless families",
		},
	}
}

var (
	spaceRun = regexp.MustCompile(`\s+`)
	// fixtureCount catches any corpus size a cited doc quotes ("113-fixture",
	// "64 lossless fixtures", "de 113 fixtures"), so a stale one in new prose
	// fails too, not only the phrases benchCitations lists.
	fixtureCount = regexp.MustCompile(`\b(\d+)(?:-fixture|(?: lossless)? fixtures)\b`)
)

// staleBenchCitations returns, for one doc's text, each expected phrase it
// lacks and each fixture count that is not a bench.md count.
func staleBenchCitations(text string, want []string, f benchFigures) []string {
	flat := spaceRun.ReplaceAllString(text, " ")
	var bad []string
	for _, w := range want {
		if !strings.Contains(flat, w) {
			bad = append(bad, "missing "+strconv.Quote(w))
		}
	}
	for _, m := range fixtureCount.FindAllStringSubmatch(flat, -1) {
		if n, _ := strconv.Atoi(m[1]); n != f.Fixtures && n != f.LosslessFixtures {
			bad = append(bad, fmt.Sprintf("%q is not a bench.md count (%d total, %d lossless)", m[0], f.Fixtures, f.LosslessFixtures))
		}
	}
	return bad
}

func TestCitedBenchFiguresMatchBenchMd(t *testing.T) {
	root := repoRoot(t)
	f, err := parseBenchFigures(mustRead(t, filepath.Join(root, "docs", "reference", "bench.md")))
	if err != nil {
		t.Fatal(err)
	}
	for doc, want := range benchCitations(f) {
		for _, b := range staleBenchCitations(mustRead(t, filepath.Join(root, filepath.FromSlash(doc))), want, f) {
			t.Errorf("%s: %s. Rule: figures cited from docs/reference/bench.md match it. Fix: update the citation (or run `make bench` and update every citation together).", doc, b)
		}
	}
}

func TestBenchFigureGuardBites(t *testing.T) {
	md := strings.Join([]string{
		"| Family | Class | Fixtures | Raw | DS | Saving % | RawT | DST | CCR bytes | CCR % |",
		"|---|---|--:|--:|--:|--:|--:|--:|--:|--:|",
		"| TOTAL | - | 10 | 100 | 50 | 50.0 | 25 | 12 | 40 | 60.0 |",
		"| Class | Fixtures | Raw bytes | Downshift bytes | Saving % |",
		"| lossless | 4 | 40 | 10 | 75.0 |",
		"## Balanced: large outputs",
		"| Fixture | Raw | L | L % | B | B % |",
		"| a | 1 | 1 | 0.0 | 1 | 0.0 |",
		"| TOTAL | 1 | 1 | 1.0 | 1 | 2.0 |",
	}, "\n")
	f, err := parseBenchFigures(md)
	if err != nil {
		t.Fatal(err)
	}
	want := benchFigures{Fixtures: 10, Raw: "50.0", CCR: "60.0", LosslessFixtures: 4, Lossless: "75.0", BalancedOutputs: 1, BalancedLossless: "1.0", Balanced: "2.0"}
	if f != want {
		t.Fatalf("parseBenchFigures = %+v, want %+v", f, want)
	}
	phrase := []string{"60.0% fewer with CCR on"}
	if bad := staleBenchCitations("60.0% fewer\n with CCR on, a 10-fixture corpus", phrase, f); len(bad) != 0 {
		t.Fatalf("matching doc flagged: %v", bad)
	}
	if bad := staleBenchCitations("61.0% fewer with CCR on, a 9-fixture corpus", phrase, f); len(bad) != 2 {
		t.Fatalf("stale doc: got %v, want the missing phrase and the 9-fixture count", bad)
	}
}
